export function getLocale(): Locale {
  if (typeof window === 'undefined') return 'en'
  const value = window.localStorage.getItem(STORAGE_KEY)
  return value === 'hi' || value === 'kn' ? value : 'en'
}

export function localeTag(locale = getLocale()) {
  return locale === 'hi' ? 'hi-IN' : locale === 'kn' ? 'kn-IN' : 'en-IN'
}

export function translate(source: string, locale = getLocale()) {
  if (locale === 'en') return source
  return copy[source]?.[locale] ?? source
}

type I18nContextValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (source: string) => string }
const I18nContext = createContext<I18nContextValue | null>(null)

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setCurrentLocale] = useState<Locale>(getLocale)
  useEffect(() => { document.documentElement.lang = locale }, [locale])
  useEffect(() => {
    const update = () => setCurrentLocale(getLocale())
    window.addEventListener('storage', update)
    window.addEventListener(LOCALE_EVENT, update)
    return () => {
      window.removeEventListener('storage', update)
      window.removeEventListener(LOCALE_EVENT, update)
    }
  }, [])
  const value = useMemo<I18nContextValue>(() => ({
    locale,
    setLocale: (next) => {
      window.localStorage.setItem(STORAGE_KEY, next)
      setCurrentLocale(next)
      window.dispatchEvent(new Event(LOCALE_EVENT))
    },
    t: (source) => translate(source, locale),
  }), [locale])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  const value = useContext(I18nContext)
  if (!value) throw new Error('useI18n must be used within I18nProvider')
  return value
}

export function LocaleSelector({ compact = false }: { compact?: boolean }) {
  const { locale, setLocale, t } = useI18n()
  return <label className={`locale-selector${compact ? ' locale-selector-compact' : ''}`}>
    <span>{t('Language')}</span>
    <select aria-label={t('Language')} value={locale} onChange={(event) => setLocale(event.target.value as Locale)}>
      <option value="en">English</option><option value="hi">हिंदी</option><option value="kn">ಕನ್ನಡ</option>
    </select>
  </label>
}

const SPEECH_KEY = 'vyapro.speech-language'
export type SpeechLocale = 'en-IN' | 'hi-IN' | 'kn-IN'
export function getSpeechLocale(): SpeechLocale {
  if (typeof window === 'undefined') return 'en-IN'
  const value = window.localStorage.getItem(SPEECH_KEY)
  if (value === 'hi-IN' || value === 'kn-IN' || value === 'en-IN') return value
  const uiLocale = getLocale()
  return uiLocale === 'hi' ? 'hi-IN' : uiLocale === 'kn' ? 'kn-IN' : 'en-IN'
}
export function setSpeechLocale(value: SpeechLocale) {
  window.localStorage.setItem(SPEECH_KEY, value)
  window.dispatchEvent(new Event('vyapro:speech-locale-change'))
}
export function SpeechLocaleSelector() {
  const [speechLocale, update] = useState<SpeechLocale>(getSpeechLocale)
  const { t } = useI18n()
  useEffect(() => {
    const listener = () => update(getSpeechLocale())
    window.addEventListener('vyapro:speech-locale-change', listener)
    return () => window.removeEventListener('vyapro:speech-locale-change', listener)
  }, [])
  return <label className="speech-locale-selector"><span>{t('Speech language')}</span>
    <select aria-label={t('Speech language')} value={speechLocale} onChange={(event) => setSpeechLocale(event.target.value as SpeechLocale)}>
      <option value="en-IN">English</option><option value="hi-IN">हिंदी</option><option value="kn-IN">ಕನ್ನಡ</option>
    </select>
  </label>
}
